macro_rules! deps { ($name:ident, [$($s:literal),* $(,)?]) => {
    static mut $name: [clkdm_dep; deps!(@n $($s),*) + 1] = [
        $(clkdm_dep { clkdm_name: concat!($s, "\0").as_ptr() },)*
        clkdm_dep { clkdm_name: core::ptr::null() },
    ];
}; (@n $($s:literal),*) => { <[()]>::len(&[$(deps!(@u $s)),*]) }; (@u $s:literal) => { () } }

