/* The following declarations preserve the C clockdomain objects and their
 * externally supplied constants. */

macro_rules! clkdm { ($n:ident, $name:literal, $p:literal, $part:expr, $inst:expr, $offs:expr $(, $field:ident = $val:expr)* $(,)?) => {
    static mut $n: clockdomain = clockdomain {
        name: concat!($name, "\0").as_ptr(), pwrdm: powerdomain { name: concat!($p, "\0").as_ptr() },
        prcm_partition: $part, cm_inst: $inst, clkdm_offs: $offs,
        dep_bit: 0, wkdep_srcs: core::ptr::null_mut(), sleepdep_srcs: core::ptr::null_mut(), flags: 0,
        $($field: $val,)*
    };
}; }

